package cn.kongj.blackstone;

import android.app.*;import android.os.*;import android.content.*;import android.provider.Settings;import android.net.Uri;import android.media.projection.MediaProjectionManager;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;

public class MainActivity extends Activity {
 static final int PERMISSIONS=0,ROLES=1,ACCOUNT=2,HOME=3,CAPTURE_SETUP=40,CAPTURE_RUN=41;
 static final int INK=0xff172b3a,MUTED=0xff657785,ACCENT=0xff246c5c;
 ScriptConfig config;RolePlan[] draft;int page,permissionAttempts,connectionPolls;boolean requestingCapture,foreground;Intent captureData;int captureCode;LinearLayout root;EditText phone,password;PasswordVisibilityView passwordVisibility;final Handler handler=new Handler();
 public void onCreate(Bundle state){super.onCreate(state);upgradeCombatPreferences(getSharedPreferences("route",0));config=new ScriptConfig(this);if(RunnerService.instance!=null)RunnerService.instance.resetToStart("助手已重新打开，下次从选角页重新开始");if(state!=null){page=state.getInt("page",config.configured()?HOME:PERMISSIONS);permissionAttempts=state.getInt("permissionAttempts",0);}else page=basicPermissions()?(config.configured()?HOME:PERMISSIONS):PERMISSIONS;showPage();}
 protected void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putInt("page",page);state.putInt("permissionAttempts",permissionAttempts);}
 protected void onResume(){super.onResume();foreground=true;connectionPolls=0;if(page==PERMISSIONS&&!requestingCapture)handler.postDelayed(()->{if(!isFinishing()&&page==PERMISSIONS)advancePermissions();},350);}
 protected void onPause(){foreground=false;if(page==ACCOUNT&&passwordVisibility!=null)passwordVisibility.hidePassword();super.onPause();}
 int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
 boolean basicPermissions(){return TouchService.instance!=null&&Settings.canDrawOverlays(this);}
 void showPage(){if(page==PERMISSIONS)showPermissions();else if(page==ROLES)showRoles();else if(page==ACCOUNT)showAccount();else showHome();}
 void shell(String title,String subtitle){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xfff3f6f5);root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(22),dp(18),dp(22),dp(28));scroll.addView(root,new android.widget.FrameLayout.LayoutParams(Math.min(getResources().getDisplayMetrics().widthPixels,dp(700)),-2,Gravity.CENTER_HORIZONTAL));setContentView(scroll);text(root,"黑石日常助手  ·  0.3.13",12,MUTED);TextView heading=text(root,title,26,INK);heading.setTypeface(null,Typeface.BOLD);text(root,subtitle,14,MUTED);}
 TextView text(LinearLayout parent,String value,int size,int color){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setPadding(0,dp(5),0,dp(5));parent.addView(t);return t;}
 LinearLayout card(LinearLayout parent){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(16),dp(12),dp(16),dp(12));GradientDrawable bg=new GradientDrawable();bg.setColor(Color.WHITE);bg.setCornerRadius(dp(12));c.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.topMargin=dp(12);parent.addView(c,p);return c;}
 Button button(LinearLayout parent,String label,Runnable action,boolean primary){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:INK);if(primary){GradientDrawable bg=new GradientDrawable();bg.setColor(ACCENT);bg.setCornerRadius(dp(9));b.setBackground(bg);}LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.topMargin=dp(12);parent.addView(b,p);b.setOnClickListener(v->action.run());return b;}
 CheckBox check(LinearLayout parent,String label,boolean value){CheckBox c=new CheckBox(this);c.setText(label);c.setTextColor(INK);c.setChecked(value);parent.addView(c);return c;}
 void toast(String message){Toast.makeText(this,message,Toast.LENGTH_LONG).show();}
 boolean activeCapture(){RunnerService s=RunnerService.instance;return s!=null&&s.projection!=null;}
 void showPermissions(){page=PERMISSIONS;shell("先准备运行权限","助手会自动检查，缺少权限时带你到系统页面开启。返回后继续检查。");LinearLayout c=card(root);text(c,TouchService.instance!=null?"✓ 无障碍服务":accessibilityEnabled()?"… 无障碍服务正在连接":"○ 无障碍服务",17,INK);text(c,(Settings.canDrawOverlays(this)?"✓ ":"○ ")+"悬浮窗",17,INK);text(c,((captureData!=null||activeCapture())?"✓ ":"○ ")+"屏幕截图授权",17,INK);text(c,"系统页面中的开关和授权需要你确认。截图授权在新的运行会话中可能需要再次确认。连接超时可在系统页面关闭并重新开启无障碍服务。",13,MUTED);button(root,"检查并申请权限",()->{permissionAttempts=0;connectionPolls=0;advancePermissions();},true);}
 boolean accessibilityEnabled(){String enabled=Settings.Secure.getString(getContentResolver(),Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES);if(enabled==null)return false;for(String value:enabled.split(":")){ComponentName name=ComponentName.unflattenFromString(value);if(name!=null&&getPackageName().equals(name.getPackageName())&&TouchService.class.getName().equals(name.getClassName()))return true;}return false;}
 void advancePermissions(){if(!foreground||requestingCapture||page!=PERMISSIONS)return;if(basicPermissions()&&(captureData!=null||activeCapture()||config.configured())){page=config.configured()?HOME:ROLES;showPage();return;}showPermissions();if(TouchService.instance==null){if(accessibilityEnabled()&&connectionPolls++<20){handler.postDelayed(this::advancePermissions,250);return;}if((permissionAttempts&1)==0){permissionAttempts|=1;openSettings(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS));}return;}if(!Settings.canDrawOverlays(this)){if((permissionAttempts&2)==0){permissionAttempts|=2;openSettings(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName())));}return;}if(captureData==null&&!activeCapture()&&(permissionAttempts&4)==0){permissionAttempts|=4;requestCapture(CAPTURE_SETUP);}}
 void openSettings(Intent intent){try{startActivity(intent);}catch(Exception e){toast("系统设置无法打开，请在模拟器设置中手动开启");}}
 void requestCapture(int request){requestingCapture=true;try{startActivityForResult(((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).createScreenCaptureIntent(),request);}catch(Exception e){requestingCapture=false;toast("系统截图授权无法打开");}}
 void showRoles(){page=ROLES;if(draft==null)draft=config.roles();shell("选择要刷的角色","按游戏选角页从上到下对应角色1～6，勾选后配置职业。仅支持已解锁黑石秘境的角色。");for(int i=0;i<6;i++)roleCard(i);button(root,"下一步 · 账号配置",()->{try{config.saveRoles(draft);showAccount();}catch(Exception e){toast(e.getMessage());}},true);if(config.configured())button(root,"返回运行首页",()->{draft=null;showHome();},false);}
 void roleCard(int index){RolePlan p=draft[index];LinearLayout c=card(root);CheckBox selected=check(c,"角色 "+(index+1),p.enabled);selected.setTextSize(18);LinearLayout details=new LinearLayout(this);details.setOrientation(1);c.addView(details);details.setVisibility(p.enabled?View.VISIBLE:View.GONE);selected.setOnCheckedChangeListener((v,enabled)->{p.enabled=enabled;details.setVisibility(enabled?View.VISIBLE:View.GONE);});check(details,"领取体力",p.recover).setOnCheckedChangeListener((v,value)->p.recover=value);LinearLayout jobs=new LinearLayout(this);details.addView(jobs);check(jobs,"合成纹章",p.craft).setOnCheckedChangeListener((v,value)->p.craft=value);check(jobs,"存入仓库",p.store).setOnCheckedChangeListener((v,value)->p.store=value);text(details,"职业",14,MUTED);Spinner spinner=new Spinner(this);ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_item,RolePlan.PROFESSIONS);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(adapter);spinner.setSelection(p.profession);details.addView(spinner);LinearLayout guide=new LinearLayout(this);guide.setOrientation(1);details.addView(guide);showGuide(guide,p);spinner.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> v){}public void onItemSelected(AdapterView<?> v,View view,int selected,long id){if(p.profession!=selected){p.profession=selected;p.position=0;p.baseForward=0;showGuide(guide,p);}}});}
 void showGuide(LinearLayout parent,RolePlan p){parent.removeAllViews();if(!p.supported())return;text(parent,"请按示意图摆放技能，保持游戏默认的技能按钮位置。",13,MUTED);parent.addView(new SkillGuideView(this,p.profession),new LinearLayout.LayoutParams(-1,dp(230)));String flow=p.profession==RolePlan.SAGE?"大招 → 减益 → 尝试增益 → 轮流使用控制、减益、增益":p.profession==RolePlan.PRIEST?"天堂审判 → 等待清场 → 原地开箱":p.controlBeforeUltimate()?"控制 → 大招 → 等待清场":"大招 → 等待清场 → 向前靠近宝箱";text(parent,flow,13,INK);if(p.profession==RolePlan.PRIEST)text(parent,"将天堂审判放在图中标注的大招位置，与元素师相同；祭祀无需前置小技能。",13,MUTED);LinearLayout adjustment=card(parent);text(adjustment,"黑石移动位置",15,INK);text(adjustment,"太靠前就点向后，太靠后就点向前；每次只微调一小档。",12,MUTED);LinearLayout arrows=new LinearLayout(this);arrows.setGravity(Gravity.CENTER_VERTICAL);adjustment.addView(arrows);Button back=new Button(this);back.setText("↓ 向后");arrows.addView(back,new LinearLayout.LayoutParams(dp(95),dp(48)));TextView value=new TextView(this);value.setTextColor(INK);value.setGravity(Gravity.CENTER);arrows.addView(value,new LinearLayout.LayoutParams(0,dp(48),1));Button forward=new Button(this);forward.setText("↑ 向前");arrows.addView(forward,new LinearLayout.LayoutParams(dp(95),dp(48)));Runnable update=()->value.setText(p.position==0?"默认位置":p.position>0?"向前 "+p.position+" 档":"向后 "+(-p.position)+" 档");update.run();back.setOnClickListener(v->{p.movePosition(-1);update.run();});forward.setOnClickListener(v->{p.movePosition(1);update.run();});}
 void showAccount(){
  page=ACCOUNT;shell("账号配置","填写后，需要重新登录时会自动使用该账号。");LinearLayout c=card(root);
  text(c,"手机号",14,INK);phone=new EditText(this);phone.setSingleLine(true);phone.setInputType(android.text.InputType.TYPE_CLASS_PHONE);phone.setHint("11位手机号");c.addView(phone);
  try{phone.setText(LoginCredentials.phone(this));}catch(Exception e){toast(e.getMessage());}
  text(c,"密码",14,INK);LinearLayout passwordRow=new LinearLayout(this);passwordRow.setGravity(Gravity.CENTER_VERTICAL);c.addView(passwordRow);
  password=new EditText(this);password.setSingleLine(true);password.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setHint("游戏登录密码");passwordRow.addView(password,new LinearLayout.LayoutParams(0,-2,1));
  passwordVisibility=new PasswordVisibilityView(this,password);passwordRow.addView(passwordVisibility,new LinearLayout.LayoutParams(dp(48),dp(48)));
  if(LoginCredentials.saved(this))try{password.setText(LoginCredentials.load(this));}catch(Exception e){toast(e.getMessage());}
  text(c,"如果游戏已自动登录，可不输入账号和密码。未配置时，遇到需要重新登录的页面会暂停，请手动登录后点击继续。",13,MUTED);
  text(c,"账号和密码仅在本机加密保存。点击密码右侧的图标可显示或隐藏原文。",13,MUTED);
  button(root,"完成配置",this::finishAccount,true);button(root,"返回角色配置",this::showRoles,false);
  button(root,"清除已保存的账号",()->new AlertDialog.Builder(this).setMessage("清除本机保存的手机号和密码？").setPositiveButton("清除",(d,w)->{LoginCredentials.clear(this);showAccount();}).setNegativeButton("取消",null).show(),false);
 }
 void finishAccount(){
  try{
   String number=phone.getText().toString().trim(),secret=password.getText().toString();
   if(number.isEmpty()&&secret.isEmpty())LoginCredentials.clear(this);
   else{if(!number.matches("1[0-9]{10}"))throw new IllegalArgumentException("请输入11位手机号，或将账号和密码都留空");if(secret.isEmpty())throw new IllegalArgumentException("请输入登录密码，或将账号和密码都留空");LoginCredentials.saveAccount(this,number,secret);}
   passwordVisibility.hidePassword();password.setText("");config.prefs.edit().remove("manualLogin").putBoolean("configured",true).apply();draft=null;showHome();
  }catch(Exception e){toast(e.getMessage());}
 }
 void showHome(){page=HOME;shell("准备好，一键开始","自动打开游戏，按勾选的角色从上到下执行。运行时浮窗会自动收起。");LinearLayout c=card(root);text(c,"本次角色",14,MUTED);text(c,config.summary(),16,INK);text(c,LoginCredentials.configured(this)?"账号：已配置自动登录":"账号：使用现有登录状态",13,MUTED);text(c,"勾选领取体力：先尝试领取，再检查是否足够刷本。不勾选：只使用已有体力。不足100体力时跳过副本及后续任务。",13,MUTED);button(root,"开始自动运行",this::startRun,true);button(root,"设置",()->{if(RunnerService.instance!=null)RunnerService.instance.resetToStart("正在修改配置，下次从选角页重新开始");draft=config.roles();showRoles();},false);}
 void startRun(){try{ScriptConfig.validate(config.roles());}catch(Exception e){toast(e.getMessage());showRoles();return;}if(!basicPermissions()){permissionAttempts=0;showPermissions();advancePermissions();return;}RunnerService service=RunnerService.instance;if(service!=null&&service.projection!=null){service.begin(true);return;}if(captureData!=null){startCapturedRun();return;}requestCapture(CAPTURE_RUN);}
 void startCapturedRun(){Intent intent=new Intent(this,RunnerService.class);intent.putExtra("capture",captureData);intent.putExtra("code",captureCode);intent.putExtra("autoLogin",true);captureData=null;startForegroundService(intent);toast("正在打开游戏并执行所选角色");}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=CAPTURE_SETUP&&request!=CAPTURE_RUN)return;requestingCapture=false;if(result!=RESULT_OK||data==null){toast("需要截图授权才能运行");if(page==PERMISSIONS)showPermissions();return;}captureData=data;captureCode=result;if(request==CAPTURE_SETUP){page=config.configured()?HOME:ROLES;showPage();}else startCapturedRun();}
 public void onBackPressed(){if(page==ACCOUNT)showRoles();else if(page==ROLES&&config.configured()){draft=null;showHome();}else super.onBackPressed();}
 static void upgradeCombatPreferences(android.content.SharedPreferences prefs){
  if(prefs.getInt("craftGapRevision",0)<1)prefs.edit().putInt("craftGapRevision",1).putInt("craftGap",300).apply();
  if(prefs.getInt("synthesisPaceRevision",0)<1){android.content.SharedPreferences.Editor e=prefs.edit().putInt("synthesisPaceRevision",1);if(prefs.getInt("craftGap",300)<600)e.putInt("craftGap",600);e.apply();}
  if(prefs.getInt("retryRevision",0)<1){android.content.SharedPreferences.Editor e=prefs.edit().putInt("retryRevision",1);if(!prefs.contains("maxRetries")||prefs.getInt("maxRetries",3)==3)e.putInt("maxRetries",20);e.apply();}
  if(prefs.getInt("chestApproachRevision",0)<1){android.content.SharedPreferences.Editor e=prefs.edit().putInt("chestApproachRevision",1);if(!prefs.contains("chestNudgeLimit")||prefs.getInt("chestNudgeLimit",3)<=3)e.putInt("chestNudgeLimit",20);e.apply();}
 }
}
